PARAMS = ['Vmax', 'Km', 'Ki', 'Kis', 'beta']
def predict(df, p):
    S = df['S'].values; I = df['I'].values
    return p['Vmax']*(S + p['beta']*S*I/p['Kis']) / (p['Km']*(1+I/p['Ki']) + S*(1+I/p['Kis']))

PARAMS = ['Vmax', 'Km', 'Ki', 'n', 'beta']
def predict(df, p):
    S = df['S'].values; I = df['I'].values
    # Hill substrate term with partial noncompetitive inhibition floor
    h = S**p['n']/(p['Km']**p['n']+S**p['n'])
    return p['Vmax']*h/(1+I/p['Ki']) + p['beta']*p['Vmax']*h*(I/p['Ki'])/(1+I/p['Ki'])

